<section><h1><?= dts_escape($role['role_name']) ?></h1><p><?= dts_escape($role['description'] ?? '') ?></p><h2>Permissions</h2><ul><?php foreach (($role['permissions'] ?? array()) as $permission): ?><li><?= dts_escape($permission['module_label'].' · '.$permission['action_label']) ?></li><?php endforeach; ?></ul><h2>Users</h2><ul><?php foreach (($role['users'] ?? array()) as $user): ?><li><?= dts_escape(trim($user['firstname'].' '.$user['lastname']).' (@'.$user['username'].')') ?></li><?php endforeach; ?></ul></section>
